-- =====================================================================
-- FARM PLAN · 007 · Contrato de Resultados, Critérios e Avaliação Semanal
-- Cria 3 tabelas novas e carrega o que já existe na planilha da Rio Juruena:
-- 34 critérios de comportamento, o contrato de cada pessoa e as notas das
-- semanas 28 a 38. Pode rodar mais de uma vez: a carga só acontece uma vez.
-- =====================================================================
create table if not exists criterios (
  id          uuid primary key default gen_random_uuid(),
  fazenda_id  uuid not null references fazendas(id) on delete cascade,
  nome        text not null,
  ativo       boolean not null default true,
  unique (fazenda_id, nome)
);
create table if not exists contrato_itens (
  id           uuid primary key default gen_random_uuid(),
  fazenda_id   uuid not null references fazendas(id) on delete cascade,
  pessoa_id    uuid not null references pessoas(id) on delete cascade,
  tipo         text not null check (tipo in ('tarefa','comportamento')),
  texto        text,                                   -- atribuição/tarefa
  criterio_id  uuid references criterios(id) on delete cascade,  -- comportamento
  ordem        int not null default 0,
  ativo        boolean not null default true
);
create table if not exists avaliacoes (
  item_id       uuid not null references contrato_itens(id) on delete cascade,
  fazenda_id    uuid not null references fazendas(id) on delete cascade,
  ano           int not null,
  semana        int not null,
  nota          numeric(4,1),            -- 0 a 10; vazio com nsa = não se aplica
  nsa           boolean not null default false,
  avaliado_por  uuid references auth.users(id),
  avaliado_em   timestamptz not null default now(),
  primary key (item_id, ano, semana)
);
alter table criterios      enable row level security;
alter table contrato_itens enable row level security;
alter table avaliacoes     enable row level security;

drop policy if exists "ver criterios" on criterios;
drop policy if exists "gerir criterios" on criterios;
drop policy if exists "ver contrato" on contrato_itens;
drop policy if exists "gerir contrato" on contrato_itens;
drop policy if exists "ver avaliacoes" on avaliacoes;
drop policy if exists "gerir avaliacoes" on avaliacoes;
create policy "ver criterios"    on criterios      for select using (fazenda_id in (select minhas_fazendas()));
create policy "gerir criterios"  on criterios      for all using (tenho_papel(fazenda_id, array['consultor','gestor','administrativo']))
                                                   with check (tenho_papel(fazenda_id, array['consultor','gestor','administrativo']));
create policy "ver contrato"     on contrato_itens for select using (fazenda_id in (select minhas_fazendas()));
create policy "gerir contrato"   on contrato_itens for all using (tenho_papel(fazenda_id, array['consultor','gestor','administrativo']))
                                                   with check (tenho_papel(fazenda_id, array['consultor','gestor','administrativo']));
create policy "ver avaliacoes"   on avaliacoes     for select using (fazenda_id in (select minhas_fazendas()));
create policy "gerir avaliacoes" on avaliacoes     for all using (tenho_papel(fazenda_id, array['consultor','gestor','administrativo']))
                                                   with check (tenho_papel(fazenda_id, array['consultor','gestor','administrativo']));

