-- Confere: itens de contrato e notas por pessoa
select p.apelido,
       count(distinct ci.id) filter (where ci.tipo = 'tarefa')        as tarefas,
       count(distinct ci.id) filter (where ci.tipo = 'comportamento') as comportamentos,
       count(a.*)                                                     as notas
from pessoas p
left join contrato_itens ci on ci.pessoa_id = p.id
left join avaliacoes a on a.item_id = ci.id
group by p.apelido order by p.apelido;